function moneyPath(p) {
  // p: [{from, to, dir, sol}] from the address back to an insider wallet; each hop printed in the direction SOL moved
  return p.map((h) => h.dir === "back" ? `${esc(short(h.to))} → ${esc(short(h.from))}` : `${esc(short(h.from))} → ${esc(short(h.to))}`)
    .map((x, i) => x + ` <span class="c-muted">(${p[i].sol} SOL)</span>`).join(" · ");
}
function beep() {
  try { const c = new (window.AudioContext || window.webkitAudioContext)(); const o = c.createOscillator(); const g = c.createGain();
    o.frequency.value = 880; g.gain.value = 0.15; o.connect(g); g.connect(c.destination); o.start(); setTimeout(() => { o.stop(); c.close(); }, 350); } catch (_) { /* no audio */ }
}
function insGroup(a) {                    // which part of the group the alerting wallet is (from why it is watched)
  const w = a.why || "";
  if (w.startsWith("new wallet funded by")) return "child";
  if (w.startsWith("deployer")) return "deployer";
  if (w.startsWith("sold for deployer")) return "seller";
  if (w.startsWith("cluster funder")) return "funder";
  if (w.startsWith("linked to")) return "linked";
  if (w.startsWith("profit")) return "profit";
  return "early";
}
